parameters.value:
=    query(
        $query: String
    )
    {
        orders(first: 1, query: $query) {
            edges {
                node {
                    name
                    cancellation{
                        staffNote
                    }
                    cancelledAt
                    cancelReason
                    closed
                    closedAt
                    confirmed
                    createdAt
                    currencyCode
                    currentCartDiscountAmountSet{
                        shopMoney{
                            amount
                            currencyCode
                        }
                    }
                    currentShippingPriceSet{
                        shopMoney{
                            amount
                            currencyCode
                        }
                    }
                    currentSubtotalLineItemsQuantity
                    currentSubtotalPriceSet{
                        shopMoney{
                            amount
                            currencyCode
                        }
                    }
                    currentTaxLines{
                        priceSet{
                            shopMoney{
                                amount
                                currencyCode
                            }
                        }
                        rate
                        title
                    }
                    currentTotalAdditionalFeesSet{
                        shopMoney{
                            amount
                            currencyCode
                        }
                    }
                    currentTotalDiscountsSet{
                        shopMoney{
                            amount
                            currencyCode
                        }
                    }
                    currentTotalDutiesSet{
                        shopMoney{
                            amount
                            currencyCode
                        }
                    }
                    currentTotalPriceSet{
                        shopMoney{
                            amount
                            currencyCode
                        }
                    }
                    currentTotalTaxSet{
                        shopMoney{
                            amount
                            currencyCode
                        }
                    }
                    currentTotalWeight
                    displayAddress{
                        address1
                        address2
                        city
                        company
                        country
                        countryCodeV2
                        firstName
                        lastName
                        phone
                        province
                        zip
                    }
                    displayFinancialStatus
                    displayFulfillmentStatus
                    email
                    lineItems(first: 250){
                        edges{
                            node{
                                currentQuantity
                                name
                                sku
                            }
                        }
                    }
                    returnStatus
                    updatedAt
                }
            }
            pageInfo {
                endCursor
                hasNextPage
            }
        }
    }
